from pysat.solvers import Glucose3
from pysat.card import CardEnc

# We need to find x[0], x[1], x[2], x[3], x[4] where each x[i] is an integer 0..5
# and x[i] = count of i in the sequence.
# Also x[2] = 2.

# Let's brute force since the search space is small.
# Each x[i] can be 0..5, so 6^5 = 7776 possibilities.

solutions = []
for x0 in range(6):
    for x1 in range(6):
        for x2 in range(6):
            if x2 != 2:
                continue
            for x3 in range(6):
                for x4 in range(6):
                    seq = [x0, x1, x2, x3, x4]
                    # Check condition
                    ok = True
                    for i in range(5):
                        if seq.count(i) != seq[i]:
                            ok = False
                            break
                    if ok:
                        solutions.append(seq)
print("Solutions:", solutions)
